locators.py.source_text:
"""Pre-submission execution of every pin locator of EXP-AUXIN-7e2e3d (TASK-20260927-64ba3f, NP-4).

Implements, literally, the parse rules of AMD-EXP-AUXIN-7e2e3d-20260926-typed
change.D1_pins.parse_rules (PR-SP800, PR-SEC2, PR-RFC5639, PR-RFC7748,
PR-IETF-DRAFT) and BOTH the refused PR-EIP197 and the corrected locator
PR-EIP197-C of AMD-EXP-AUXIN-7e2e3d-20260927-narrow, then the cross-source,
internal-consistency and family checks, the C-FIELD extraction cross-checks, and
the FP construction of the corrected confounder clause with its M-FP mutation.

OUTPUT DISCIPLINE: no integer is printed in decimal or hex. Each extracted integer
is reported by bit length and by sha256 of its ASCII decimal representation
(no sign, no leading zeros, no newline). Match counts, line numbers and booleans
are printed. Zero runs; nothing is factored; no primality is proved here.

Usage: python3 -I locators.py <repo_root> <sources_dir>
"""
import hashlib
import json
import re
import sys

REPO = SRC = None
WS = "\t\n\x0b\x0c\r \x85\xa0"
WS_RE = "[" + re.escape(WS) + "]"


TYPED_REL = "experiments/EXP-AUXIN-7e2e3d/amendments/AMD-20260926-typed.yaml"
TYPED_SHA = "3c57978c91b632226c0e0543913f8a122bb16d121b0a308254b1c99cedeeaad6"


def eval_pow2_sum(expr):
    """Exact value of a signed sum of terms, each 2^k or a decimal integer."""
    s = expr.replace(" ", "")
    assert re.fullmatch(r"[0-9^+\-]+", s), "unexpected expression form"
    total = 0
    for sign, term in re.findall(r"([+\-]?)([0-9]+(?:\^[0-9]+)?)", s):
        v = 2 ** int(term.split("^")[1]) if "^" in term else int(term)
        assert "^" not in term or term.split("^")[0] == "2"
        total += -v if sign == "-" else v
    return total


def cfield_values():
    text, digest = read_text(f"{REPO}/{TYPED_REL}")
    assert digest == TYPED_SHA, "held file digest mismatch"
    vals = {}
    for cid in ("CF-1", "CF-2"):
        m = re.search(r"- id: " + cid + r"\n\s+value: ([^\n]+)\n", text)
        vals[cid] = eval_pow2_sum(m.group(1))
    return vals["CF-1"], vals["CF-2"]


def dig(n):
    return {"bits": n.bit_length(), "sha256_dec": hashlib.sha256(str(n).encode()).hexdigest()}


def read_text(path):
    b = open(path, "rb").read()
    return b.decode("utf-8", errors="strict"), hashlib.sha256(b).hexdigest()


def lines_of(text):
    return text.split("\n")  # LF only (definitions.line_numbering)


def strip(s):
    return s.strip(WS)


def rm_ws(s, backslash=False):
    out = "".join(c for c in s if c not in WS)
    return out.replace("\\", "") if backslash else out


class LocatorFailure(Exception):
    pass


# ---------------------------------------------------------------- PR-SP800
def pr_sp800(text, section, label):
    L = lines_of(text)
    start = next((i for i, l in enumerate(L) if strip(l) == section), None)
    if start is None:
        raise LocatorFailure("block start not found")
    end = next((j for j in range(start + 1, len(L)) if re.fullmatch(r"[0-9]+(\.[0-9]+)*\.", strip(L[j]))), len(L))
    block = L[start:end]
    li = next((k for k, l in enumerate(block) if l.lstrip(WS).startswith(label + ":")), None)
    if li is None:
        raise LocatorFailure("label line not found")
    # character stream of the block from after "L:"
    first = block[li]
    pos = first.index(label + ":") + len(label) + 1
    rest_lines = [first[pos:]] + block[li + 1:]
    stream = "\n".join(rest_lines)
    # (b): start of the next line in block whose stripped content matches ^[A-Za-z]{1,4}:
    b_off = None
    off = len(rest_lines[0]) + 1
    for k in range(1, len(rest_lines)):
        if re.match(r"^[A-Za-z]{1,4}:", strip(rest_lines[k])):
            b_off = off
            break
        off += len(rest_lines[k]) + 1
    a_off = stream.find("(")
    a_off = None if a_off < 0 else a_off
    if a_off is not None and (b_off is None or a_off < b_off):
        span, ended_by_a = stream[:a_off], True
    else:
        span, ended_by_a = (stream[:b_off] if b_off is not None else stream), False
    dec = rm_ws(span, backslash=True)
    dec_clean = bool(dec) and dec.isdigit() and all(c in "0123456789" for c in dec)
    hexv = None
    if ended_by_a:
        after = rm_ws(stream[a_off + 1:])
        if after.startswith("=0x"):
            raw_after = stream[a_off + 1:]
            k0 = raw_after.find("0x") + 2
            k1 = raw_after.find(")", k0)
            h = rm_ws(raw_after[k0:k1]) if k1 >= 0 else ""
            hexv = h if (h and all(c in "0123456789abcdefABCDEF" for c in h)) else "CONTAMINATED"
    rec = {"label_line": start + li + 1, "block_first_line": start + 1, "block_last_line": end,
           "decimal_form": "clean" if dec_clean else "contaminated",
           "hex_form": "absent" if hexv is None else ("contaminated" if hexv == "CONTAMINATED" else "clean")}
    if hexv not in (None, "CONTAMINATED"):
        V = int(hexv, 16)
        rec["representation"] = "hex"
        rec["printed_digits"] = hexv.lower()
        if dec_clean:
            if len(dec) == len(str(V)):
                if int(dec) != V:
                    raise LocatorFailure("decimal form differs from hex form")
                rec["decimal_compared"] = "equal"
            else:
                rec["decimal_compared"] = "decimal_span_not_a_literal"
        return V, rec
    if dec_clean:
        rec["representation"] = "decimal"
        rec["printed_digits"] = dec
        return int(dec), rec
    raise LocatorFailure("neither form clean")


# ---------------------------------------------------------------- PR-SEC2
def pr_sec2(text, curve, label):
    L = lines_of(text)
    pat = re.compile(r"^[0-9]+(\.[0-9]+)+RecommendedParameters" + re.escape(curve) + r"$")
    start = next((i for i, l in enumerate(L) if pat.match(rm_ws(l))), None)
    if start is None:
        raise LocatorFailure("block start not found")
    end = next((j for j in range(start + 1, len(L)) if "RecommendedParameters" in L[j]), len(L))
    B = L[start:end]

    def next_nonempty(k):
        for j in range(k + 1, len(B)):
            if strip(B[j]):
                return j
        return None

    li = None
    for k, l in enumerate(B):
        if strip(l) == label:
            j = next_nonempty(k)
            if j is not None and B[j].lstrip(WS).startswith("="):
                li, eq = k, j
                break
    if li is None:
        raise LocatorFailure("label line not found")
    after_eq = rm_ws(B[eq].lstrip(WS)[1:])
    if after_eq:
        vals, nxt = [after_eq], eq + 1
    else:
        j = next_nonempty(eq)
        if j is None:
            raise LocatorFailure("no value line")
        vals, nxt = [rm_ws(B[j])], j + 1
    if not vals[0] or not all(c in "0123456789abcdefABCDEF" for c in vals[0]):
        raise LocatorFailure("first value line not hex")
    for j in range(nxt, len(B)):
        s = rm_ws(B[j])
        if len(s) >= 4 and all(c in "0123456789abcdefABCDEF" for c in s):
            vals.append(s)
        else:
            break
    h = "".join(vals)
    return int(h, 16), {"label_line": start + li + 1, "block_first_line": start + 1, "value_lines": len(vals),
                        "representation": "hex", "printed_digits": h.lower()}


# ---------------------------------------------------------------- PR-RFC5639
def pr_rfc5639(text, curve, label):
    L = lines_of(text)
    start = next((i for i, l in enumerate(L) if strip(l) == "Curve-ID: " + curve), None)
    if start is None:
        raise LocatorFailure("block start not found")
    end = len(L)
    for j in range(start + 1, len(L)):
        s = strip(L[j])
        if s.startswith("Curve-ID:") or s.startswith("#Twisted") or re.match(r"^[0-9]+(\.[0-9]+)*\.\s", s):
            end = j
            break
    B = L[start:end]
    li = next((k for k, l in enumerate(B) if strip(l).startswith(label + " =") or strip(l) == label + " ="), None)
    if li is None:
        raise LocatorFailure("label line not found")
    parts = [B[li].split("=", 1)[1]]
    for j in range(li + 1, len(B)):
        s = strip(B[j])
        if s and all(c in "0123456789abcdefABCDEF" for c in rm_ws(s)):
            parts.append(B[j])
        else:
            break
    h = rm_ws("".join(parts))
    if not h or not all(c in "0123456789abcdefABCDEF" for c in h):
        raise LocatorFailure("value not hex")
    return int(h, 16), {"label_line": start + li + 1, "block_first_line": start + 1, "representation": "hex"}


# ---------------------------------------------------------------- PR-RFC7748
def pr_rfc7748(text, label):
    L = lines_of(text)
    start = next((i for i, l in enumerate(L) if strip(l) == "4.1.  Curve25519"), None)
    if start is None:
        raise LocatorFailure("section 4.1 not found")
    end = next((j for j in range(start + 1, len(L)) if re.match(r"^[0-9]+(\.[0-9]+)*\.\s", strip(L[j]))), len(L))
    B = L[start:end]
    li = next((k for k, l in enumerate(B) if re.match("^" + re.escape(label) + WS_RE + "+", strip(l))), None)
    if li is None:
        raise LocatorFailure("label line not found")
    expr = rm_ws(strip(B[li])[len(label):])
    m1 = re.fullmatch(r"2\^([0-9]+)\+0x([0-9A-Fa-f]+)", expr)
    m2 = re.fullmatch(r"2\^([0-9]+)-([0-9]+)", expr)
    if m1:
        v = 2 ** int(m1.group(1)) + int(m1.group(2), 16)
    elif m2:
        v = 2 ** int(m2.group(1)) - int(m2.group(2))
    else:
        raise LocatorFailure("expression form not recognised")
    return v, {"label_line": start + li + 1, "form": "2^E + 0xH" if m1 else "2^E - S"}


# ---------------------------------------------------------------- PR-IETF-DRAFT
def pr_ietf(text, label):
    L = lines_of(text)
    start = next((i for i, l in enumerate(L) if re.match(r"^[0-9]+(\.[0-9]+)*\.\s.*\(BLS12-381\)$", strip(l))), None)
    if start is None:
        raise LocatorFailure("block start not found")
    end = next((j for j in range(start + 1, len(L)) if re.match(r"^[0-9]+(\.[0-9]+)*\.\s", strip(L[j]))), len(L))
    B = L[start:end]

    def norm(l):
        s = strip(l)
        if s.startswith("*"):
            s = strip(s[1:])
        return s

    li = next((k for k, l in enumerate(B) if re.match("^" + re.escape(label) + r"\s*[:=]", norm(l))), None)
    if li is None:
        raise LocatorFailure("label line not found")
    s = norm(B[li])
    cut = min([p for p in (s.find(":"), s.find("=")) if p >= 0])
    parts = [s[cut + 1:]]
    allowed = re.compile(r"^(?:[0-9A-Fa-f]|0x|x|\^|\+|-|" + WS_RE + ")+$")
    for j in range(li + 1, len(B)):
        t = strip(B[j])
        if t and allowed.match(t):
            parts.append(t)
        else:
            break
    v = rm_ws("".join(parts))
    if re.fullmatch(r"-?0x[0-9A-Fa-f]+", v):
        val = int(v, 16)
        form = "hex"
    elif re.fullmatch(r"-?[0-9]+", v):
        val = int(v)
        form = "decimal"
    elif re.fullmatch(r"-?2\^[0-9]+([+-]2\^[0-9]+)*", v):
        val = 0
        for sign, e in re.findall(r"([+-]?)2\^([0-9]+)", v):
            val += -(2 ** int(e)) if sign == "-" else 2 ** int(e)
        form = "powers_of_two"
    else:
        raise LocatorFailure("value text form not recognised")
    return val, {"label_line": start + li + 1, "block_first_line": start + 1, "form": form}


# ---------------------------------------------------------------- PR-EIP197
EIP_REFUSED_R = r"prime order q\s*=\s*([0-9]+)"
EIP_REFUSED_P = r"(?<![A-Za-z0-9_])p\s*=\s*([0-9]+)"
EIP_C_R = r"prime order \x60q\s*=\s*([0-9]+)\x60"
EIP_C_P = r"over the field \x60F_p\x60 with \x60p\s*=\s*([0-9]+)\x60"


def eip(text, rx):
    ms = list(re.finditer(rx, text))
    rec = {"regex": rx, "match_count": len(ms)}
    if ms:
        rec["first_match_line"] = text.count("\n", 0, ms[0].start()) + 1
    return (int(ms[0].group(1)) if ms else None), rec


# ---------------------------------------------------------------- run
def run():
    S = REPO + "/inputs/SAFECURVES-20260825/specs/"
    T = {}
    H = {}
    for n in ["sp800-186.txt", "sec2-v2.txt", "rfc5639.txt", "rfc7748.txt"]:
        T[n], H[n] = read_text(S + n)
    T["eip-197.md"], H["eip-197.md"] = read_text(SRC + "/eip-197.md")
    dname = "draft-irtf-cfrg-pairing-friendly-curves-14.txt"
    T[dname], H[dname] = read_text(SRC + "/" + dname)
    out = {"source_sha256": H, "rows": {}, "values_withheld": "decimal and hex never printed"}
    V = {}

    def do(row, key, fn, *a):
        try:
            v, rec = fn(*a)
            rec = {k: w for k, w in rec.items() if k != "printed_digits"}
            rec.update(dig(v))
            rec["result"] = "value"
            V[(row, key)] = v
        except LocatorFailure as e:
            rec = {"result": "locator_failure", "reason": str(e)}
        out["rows"].setdefault(row, {})[key] = rec

    sp = T["sp800-186.txt"]
    for row, sec, sc in [("NIST-P-224", "3.2.1.2.", "secp224r1"), ("NIST-P-256", "3.2.1.3.", "secp256r1"),
                         ("NIST-P-384", "3.2.1.4.", "secp384r1"), ("NIST-P-521", "3.2.1.5.", "secp521r1")]:
        for lab, key in [("n", "r"), ("p", "p"), ("h", "h")]:
            do(row, key, pr_sp800, sp, sec, lab)
        do(row, "cross_source_n", pr_sec2, T["sec2-v2.txt"], sc, "n")
    for lab, key in [("n", "r"), ("p", "p"), ("h", "h")]:
        do("secp256k1", key, pr_sec2, T["sec2-v2.txt"], "secp256k1", lab)
    for row in ["brainpoolP256r1", "brainpoolP384r1"]:
        for lab, key in [("q", "r"), ("p", "p"), ("h", "h")]:
            do(row, key, pr_rfc5639, T["rfc5639.txt"], row, lab)
    for lab, key in [("n", "r"), ("p", "p"), ("h", "h")]:
        do("Ed25519-L", key, pr_sp800, sp, "3.2.3.1.", lab)
    do("Ed25519-L", "cross_source_order", pr_rfc7748, T["rfc7748.txt"], "order")
    for lab, key in [("r", "r"), ("p", "p"), ("h", "h"), ("t", "t")]:
        do("BLS12-381-r", key, pr_ietf, T[dname], lab)
    # EIP-197: refused locator and corrected locator
    e = T["eip-197.md"]
    rv, rrec = eip(e, EIP_REFUSED_R)
    pv, prec = eip(e, EIP_REFUSED_P)
    out["rows"]["BN254-r"] = {"refused_PR-EIP197_r": rrec, "refused_PR-EIP197_p": prec}
    if pv is not None:
        out["rows"]["BN254-r"]["refused_PR-EIP197_p"].update(dig(pv))
    cr, crec = eip(e, EIP_C_R)
    cp, cprec = eip(e, EIP_C_P)
    if cr is not None:
        crec.update(dig(cr))
        V[("BN254-r", "r")] = cr
    if cp is not None:
        cprec.update(dig(cp))
        V[("BN254-r", "p")] = cp
    crec["result"] = "value" if crec["match_count"] == 1 else "locator_failure"
    cprec["result"] = "value" if cprec["match_count"] == 1 else "locator_failure"
    out["rows"]["BN254-r"]["corrected_PR-EIP197-C_r"] = crec
    out["rows"]["BN254-r"]["corrected_PR-EIP197-C_p"] = cprec
    out["rows"]["BN254-r"]["refused_p_equals_corrected_p"] = (pv is not None and pv == cp)

    # cross-checks (booleans only)
    chk = {}
    for row, key in [("NIST-P-224", "cross_source_n"), ("NIST-P-256", "cross_source_n"),
                     ("NIST-P-384", "cross_source_n"), ("NIST-P-521", "cross_source_n")]:
        chk[row + ":sec2_n_equals_sp800_n"] = V.get((row, "r")) is not None and V.get((row, "r")) == V.get((row, key))
    chk["Ed25519-L:rfc7748_order_equals_sp800_n"] = V.get(("Ed25519-L", "r")) == V.get(("Ed25519-L", "cross_source_order"))
    # internal consistency vs specification.yaml (compare only)
    try:
        import yaml  # optional; stdlib-only fallback below
        spec = yaml.safe_load(open(REPO + "/experiments/EXP-AUXIN-7e2e3d/specification.yaml"))
        fl = spec["experiment"]["inputs"]["parameters"]["frozen_curve_list"]
        for rr in fl:
            if "r_hex_pinned_internal" in rr:
                chk[rr["id"] + ":internal_consistency_r_hex_pinned_internal"] = (
                    int(str(rr["r_hex_pinned_internal"]), 16) == V.get((rr["id"], "r")))
    except ImportError:
        chk["internal_consistency"] = "not evaluated (yaml unavailable under -I)"
    # BN family check
    p = V.get(("BN254-r", "p"))
    r = V.get(("BN254-r", "r"))
    bn_ok, bn_u_found = False, False
    if p is not None and r is not None:
        def iroot4(n):
            x = int(round(n ** 0.25)) if n < 2 ** 1000 else 1 << (n.bit_length() // 4)
            while x ** 4 > n:
                x -= 1
            while (x + 1) ** 4 <= n:
                x += 1
            return x
        base = iroot4(p // 36)
        for u in list(range(base - 3, base + 4)) + list(range(-base - 3, -base + 4)):
            if 36 * u ** 4 + 36 * u ** 3 + 24 * u ** 2 + 6 * u + 1 == p:
                bn_u_found = True
                bn_ok = (36 * u ** 4 + 36 * u ** 3 + 18 * u ** 2 + 6 * u + 1 == r)
                chk["BN254-r:family_u"] = dig(abs(u)) | {"sign": "+" if u > 0 else "-"}
    chk["BN254-r:family_u_found"] = bn_u_found
    chk["BN254-r:family_check"] = bn_ok
    t = V.get(("BLS12-381-r", "t"))
    rb, pb = V.get(("BLS12-381-r", "r")), V.get(("BLS12-381-r", "p"))
    if None not in (t, rb, pb):
        num = (t - 1) ** 2 * (t ** 4 - t ** 2 + 1)
        chk["BLS12-381-r:family_check"] = (rb == t ** 4 - t ** 2 + 1) and num % 3 == 0 and pb == num // 3 + t
    # C-FIELD extraction cross-checks (held clause). The two closed-form case values are
    # read from the hash-bound held file at run time and never written in this program.
    CF1, CF2 = cfield_values()
    chk["CF-1_equals_Ed25519-L_extracted_p"] = V.get(("Ed25519-L", "p")) == CF1
    chk["CF-2_equals_NIST-P-256_extracted_p"] = V.get(("NIST-P-256", "p")) == CF2
    out["checks"] = chk

    # corrected FP and its mutation (booleans and counts only)
    rows = ["NIST-P-224", "NIST-P-256", "NIST-P-384", "NIST-P-521", "secp256k1", "brainpoolP256r1",
            "brainpoolP384r1", "Ed25519-L", "BN254-r", "BLS12-381-r"]
    extracted = {row: V[(row, "p")] for row in rows if (row, "p") in V}
    FP = set(extracted.values())
    MFP = {CF1, CF2}
    fp = {"rows_with_extracted_field_prime": len(extracted), "distinct_extracted_field_primes": len(FP),
          "rows_without_extracted_field_prime": [x for x in rows if x not in extracted]}

    def clause1(c, S):
        return c in S

    # C-FIELD-EXTRACTED: every extracted field prime, presented as r, must carry field_prime first.
    ok_correct = all(clause1(v, FP) for v in extracted.values())
    fails_under_mfp = [row for row, v in extracted.items() if not clause1(v, MFP)]
    fp["C-FIELD-EXTRACTED_passes_under_corrected_FP"] = ok_correct
    fp["C-FIELD-EXTRACTED_cases_failing_under_M-FP"] = fails_under_mfp
    fp["C-FIELD-EXTRACTED_fails_under_M-FP"] = len(fails_under_mfp) > 0
    fp["PTM-B_brainpoolP384r1_p_rejected_by_field_prime_under_corrected_FP"] = clause1(extracted.get("brainpoolP384r1"), FP)
    fp["PTM-B_brainpoolP384r1_p_rejected_by_field_prime_under_M-FP"] = clause1(extracted.get("brainpoolP384r1"), MFP)
    fp["CF-1_in_corrected_FP"] = CF1 in FP
    fp["CF-2_in_corrected_FP"] = CF2 in FP
    # no deployed r collides with any extracted field prime (clause (1) on deployed rows)
    fp["deployed_r_values_in_corrected_FP"] = [row for row in rows if V.get((row, "r")) in FP]
    out["fp_and_mutation"] = fp
    out["pdf_printed_digit_sha256"] = {}
    return out, V


if __name__ == "__main__":
    REPO, SRC = sys.argv[1], sys.argv[2]
    o, _ = run()
    print(json.dumps(o, indent=1, sort_keys=True))

