"""Execute the CORRECTED admission items 1 (PARI line), 3 and 4 exactly as written in
AMD-EXP-AUXIN-7e2e3d-20260927-narrow (zero-run tool probe, TASK-20260927-64ba3f).

Usage: python3 admission_items.py <venv-python> [<venv-python> ...]. Prints JSON.
The program texts below are the texts the amendment quotes; their sha256 digests are
printed so the amendment and this transcript can be compared byte for byte.
"""
import hashlib
import json
import re
import subprocess
import sys
import time

ITEM1_PARI_PROGRAM = (
    "import importlib.metadata as m, cypari2; p = cypari2.Pari(); "
    "print(m.version('cypari2')); print(m.version('cysignals')); "
    "print('.'.join(str(int(x)) for x in p.version()[:3]))"
)

ITEM3_PROGRAM = """import cypari2
from cysignals.signals import AlarmInterrupt
p = cypari2.Pari(size=2**27, sizemax=2**32)
for e in ('alarm(1, while(1, ))', 'alarm(1, factor(nextprime(2^140)*nextprime(2^141)))'):
    try:
        p(e)
        print('RETURNED')
    except AlarmInterrupt:
        print('ALARM')
print(p('2+2'))
"""

ITEM4_STACK_PROGRAM = """import time, cypari2
p = cypari2.Pari(size=2**27, sizemax=2**32)
for e in ('2^89-1', '2^607-1'):
    t0 = time.monotonic()
    c = p.primecert(p(e))
    ok = int(p.primecertisvalid(c))
    print(e, 'valid' if ok == 1 else 'INVALID', round(time.monotonic() - t0, 3))
"""


def three_ints(s):
    return bool(re.fullmatch(r"[0-9]+\.[0-9]+\.[0-9]+", s))


def ge(a, b):
    return tuple(int(x) for x in a.split(".")) >= tuple(int(x) for x in b.split("."))


out = {"program_sha256": {k: hashlib.sha256(v.encode()).hexdigest() for k, v in
                          [("ITEM1_PARI_PROGRAM", ITEM1_PARI_PROGRAM), ("ITEM3_PROGRAM", ITEM3_PROGRAM),
                           ("ITEM4_STACK_PROGRAM", ITEM4_STACK_PROGRAM)]},
       "builds": []}
for py in sys.argv[1:]:
    rec = {"python": py}
    cp = subprocess.run([py, "--version"], capture_output=True, text=True)
    rec["python_version"] = (cp.stdout or cp.stderr).strip()
    cp = subprocess.run([py, "-I", "-c", ITEM1_PARI_PROGRAM], capture_output=True, text=True, timeout=60)
    lines = cp.stdout.strip().split("\n")
    rec["item1"] = {"exit_status": cp.returncode, "stdout_lines": lines, "stderr_tail": cp.stderr.strip()[-200:]}
    if cp.returncode == 0 and len(lines) == 3 and three_ints(lines[0]) and three_ints(lines[2]):
        rec["item1"]["verdict"] = "pass" if (ge(lines[0], "2.1.5") and ge(lines[2], "2.15.4")) else "fail_below_minimum"
    else:
        rec["item1"]["verdict"] = "fail_not_executable_or_unparseable"
    t0 = time.monotonic()
    try:
        cp = subprocess.run([py, "-I", "-c", ITEM3_PROGRAM], capture_output=True, text=True, timeout=10)
        lines = cp.stdout.strip().split("\n") if cp.stdout.strip() else []
        rec["item3"] = {"exit_status": cp.returncode, "stdout_lines": lines,
                        "stderr_tail": cp.stderr.strip()[-160:],
                        "verdict": "pass" if (cp.returncode == 0 and lines == ["ALARM", "ALARM", "4"]) else "fail"}
    except subprocess.TimeoutExpired:
        rec["item3"] = {"exit_status": "killed_at_10s", "verdict": "fail"}
    rec["item3"]["wall_s"] = round(time.monotonic() - t0, 3)
    try:
        cp = subprocess.run([py, "-I", "-c", ITEM4_STACK_PROGRAM], capture_output=True, text=True, timeout=900)
        rec["item4_stack"] = {"exit_status": cp.returncode, "stdout_lines": cp.stdout.strip().split("\n"),
                              "stderr_tail": cp.stderr.strip()[-160:]}
    except subprocess.TimeoutExpired:
        rec["item4_stack"] = {"exit_status": "killed_at_900s"}
    out["builds"].append(rec)
print(json.dumps(out, indent=1))

