"""Build AMD-20260927-narrow.yaml from narrow_template.yaml (TASK-20260927-64ba3f).

Fills every span digest from the hash-bound held file, generates the governing-text
table, and checks the result: spans resolve uniquely, program digests equal the executed
ones, no incorporated held field is retyped, no forbidden value appears, and the table is
total with exactly one layer per field. Prints a JSON check report.
"""
import hashlib
import json
import re
import sys

import yaml

S = "/Volumes/SSD990/tmp/auxin-64ba3f"
REPO = sys.argv[1]
OUT = sys.argv[2]
REPORT = sys.argv[3]
TYPED_PATH = f"{REPO}/experiments/EXP-AUXIN-7e2e3d/amendments/AMD-20260926-typed.yaml"
SPEC_PATH = f"{REPO}/experiments/EXP-AUXIN-7e2e3d/specification.yaml"
TYPED_SHA = "3c57978c91b632226c0e0543913f8a122bb16d121b0a308254b1c99cedeeaad6"


def sha(s):
    return hashlib.sha256(s if isinstance(s, bytes) else s.encode("utf-8")).hexdigest()


typed_bytes = open(TYPED_PATH, "rb").read()
assert sha(typed_bytes) == TYPED_SHA
typed = yaml.safe_load(typed_bytes)["amendment"]
spec = yaml.safe_load(open(SPEC_PATH))["experiment"]
tmpl = open(f"{S}/narrow_template.yaml").read()
draft = yaml.safe_load(tmpl.replace("@@GOVERNING_TEXT_TABLE@@", "    []"))["amendment"]
checks = {}


def resolve(root, path):
    node = root
    for seg in path.split("."):
        m = re.fullmatch(r"([^\[]+)(?:\[([^\]]+)\])?", seg)
        key, sel = m.group(1), m.group(2)
        node = node[key]
        if sel is not None:
            hits = [x for x in node if isinstance(x, dict) and x.get("id") == sel]
            assert len(hits) == 1, (path, sel)
            node = hits[0]
    return node


# ------------------------------------------------------------------ spans
span_report = {}
filled = tmpl
for sp in draft["span_rules"]:
    val = resolve(typed, sp["field"])
    assert isinstance(val, str), sp["id"]
    assert val.count(sp["from"]) == 1, (sp["id"], "from not unique", val.count(sp["from"]))
    i = val.index(sp["from"])
    j = val.index(sp["through"], i) + len(sp["through"])
    span = val[i:j]
    d = sha(span)
    span_report[sp["id"]] = {"field": sp["field"], "chars": len(span), "sha256": d}
    filled = filled.replace(f'"@@SPAN:{sp["id"]}@@"', d)
assert "@@SPAN:" not in filled

# whole-field replacements: record the held digest of what is replaced
whole = {
    "tools_and_admission.certificate_and_factoring_library.minimum_version":
        typed["tools_and_admission"]["certificate_and_factoring_library"]["minimum_version"],
    "tools_and_admission.certificate_and_factoring_library.version_command":
        typed["tools_and_admission"]["certificate_and_factoring_library"]["version_command"],
    "change.D3_descriptive_bins.bin_by_status": typed["change"]["D3_descriptive_bins"]["bin_by_status"],
    "interpretation_limits item 6": typed["interpretation_limits"][5],
}
assert typed["interpretation_limits"][5].startswith("On the two pairing-family rows")
checks["whole_field_replacements_held_sha256"] = {k: sha(v) for k, v in whole.items()}

# ------------------------------------------------------------------ governing table
span_by_field = {}
for sp in draft["span_rules"]:
    span_by_field.setdefault(sp["field"], []).append(sp["id"])
whole_fields = {
    "tools_and_admission.certificate_and_factoring_library.minimum_version": "corrective.tools.certificate_and_factoring_library.minimum_version",
    "tools_and_admission.certificate_and_factoring_library.version_command": "corrective.tools.certificate_and_factoring_library.version_command",
    "change.D3_descriptive_bins.bin_by_status": "corrective.bin_by_status",
    "interpretation_limits item 6": "corrective.interpretation_limits_item_6",
}
envelope = {"id", "predecessor_amendment", "predecessor_status", "batch_id", "producer_task",
            "producer_snapshot", "review_plan_id", "decision_id", "decision_id_note", "recorded_at",
            "kind", "status", "approval", "defect", "cites", "authorization"}
identity_same = {"experiment_id", "hypothesis_id", "question_id", "goal_id"}


def leaves(node, path):
    if isinstance(node, dict):
        for k, v in node.items():
            yield from leaves(v, f"{path}.{k}" if path else str(k))
    elif isinstance(node, list) and node and all(isinstance(x, dict) and "id" in x for x in node):
        for x in node:
            for k, v in x.items():
                if k == "id":
                    continue
                yield from leaves(v, f"{path}[{x['id']}].{k}")
    elif isinstance(node, list) and node and not any(isinstance(x, (dict, list)) for x in node):
        for n, x in enumerate(node, 1):
            yield f"{path} item {n}"
    else:
        yield path


rows = []
for top, v in typed.items():
    if top in envelope:
        for p in leaves(v, top):
            rows.append({"field": f"typed:{p}", "layer": "corrective",
                         "via": "envelope_not_incorporated; this file's field of the same role governs"})
        continue
    if top in identity_same:
        rows.append({"field": f"typed:{top}", "layer": "corrective",
                     "via": "identity field; this file states the same value"})
        continue
    for p in leaves(v, top):
        if p in whole_fields:
            rows.append({"field": f"typed:{p}", "layer": "corrective", "via": whole_fields[p]})
        elif p in span_by_field:
            ids = span_by_field[p]
            for sid in ids:
                rows.append({"field": f"typed:{p} span {sid}", "layer": "corrective", "via": f"span_rules[{sid}].replacement"})
            rows.append({"field": f"typed:{p} outside span{'s' if len(ids) > 1 else ''} {', '.join(ids)}",
                         "layer": "refused-typed-by-hash", "via": "incorporates.sha256"})
        else:
            rows.append({"field": f"typed:{p}", "layer": "refused-typed-by-hash", "via": "incorporates.sha256"})

assert {r["field"] for r in rows if r["field"].startswith("typed:interpretation_limits item 6")}

V1_TYPED = [
    (r"^hypothesis_id$", "held supersedes_fields item 1"),
    (r"^inputs\.procedure$", "held supersedes_fields item 2 (replaced by held stages)"),
    (r"^inputs\.instrument$", "held supersedes_fields item 3"),
    (r"^inputs\.parameters\.frozen_curve_list\[[^\]]+\]\.r_pin_source$", "held supersedes_fields item 4 (held change.D1_pins.rows)"),
    (r"^inputs\.parameters\.confounder_field_vs_order$", "held supersedes_fields item 5"),
    (r"^inputs\.parameters\.(cost_expression|E_r)$", "held supersedes_fields item 6"),
    (r"^inputs\.parameters\.(e_inert_floor|e_escalate_ceiling)$", "held supersedes_fields item 7 (retired)"),
    (r"^controls\[(positive_planted_divisor|null_safeprime_r_minus_1)\]", "held supersedes_fields item 8"),
    (r"^controls\[ordering\]", "held supersedes_fields item 9 (held stages and C-ORDER)"),
    (r"^independent_variables\[curve_id\]\.values item (11|12)$", "held supersedes_fields item 10 (PLANTED, SAFEPRIME)"),
    (r"^metrics\.", "held supersedes_fields items 11 and 18"),
    (r"^preregistered_prediction\.", "held supersedes_fields item 12"),
    (r"^tail_checks item 4$", "held supersedes_fields item 13 (removed)"),
    (r"^replication\.seeds", "held supersedes_fields item 14"),
    (r"^stopping_rules item (1|4)$", "held supersedes_fields item 15"),
    (r"^(success_criterion|falsification_criterion)", "held supersedes_fields item 16"),
    (r"^required_artifacts", "held supersedes_fields item 17"),
    (r"^launch_gate\.blocks_scientific_run_until item (1|3)$", "held supersedes_fields item 18 (meaning fixed by held D7, D8)"),
    (r"^cost_model_disclosure\.(model|unit)$", "held supersedes_fields item 19"),
    (r"^stages\[(stage0_order_pin|stage1_divisor_census)\]\.purpose$", "held supersedes_fields item 2 (Stage 0 and Stage 1 steps replaced by held stages)"),
]


def v1_leaves(node, path):
    if isinstance(node, dict):
        for k, v in node.items():
            yield from v1_leaves(v, f"{path}.{k}" if path else str(k))
    elif isinstance(node, list) and node and all(isinstance(x, dict) for x in node):
        for x in node:
            key = x.get("id") or x.get("kind") or x.get("name")
            for k, v in x.items():
                if x.get(k) == key and k in ("id", "kind", "name"):
                    continue
                yield from v1_leaves(v, f"{path}[{key}].{k}")
    elif isinstance(node, list) and node:
        for n, _ in enumerate(node, 1):
            yield f"{path} item {n}"
    else:
        yield path


v1_rows = []
for p in v1_leaves(spec, ""):
    via = next((why for rx, why in V1_TYPED if re.search(rx, p)), None)
    if via:
        v1_rows.append({"field": f"v1:{p}", "layer": "refused-typed-by-hash", "via": via})
    else:
        v1_rows.append({"field": f"v1:{p}", "layer": "v1", "via": "not superseded by the held text or by this file"})
# sanity: independent_variables item 11/12 are PLANTED/SAFEPRIME
assert spec["independent_variables"][0]["values"][10:12] == ["PLANTED", "SAFEPRIME"]
for rx, _ in V1_TYPED:
    assert any(re.search(rx, r["field"][3:]) for r in v1_rows), ("unused v1 rule", rx)

other_rows = [
    {"field": "file:AMD-20260916-bands.yaml (every field)", "layer": "refused-typed-by-hash",
     "via": "held supersedes_fields last item: no field governs a run"},
    {"field": "file:AMD-20260923-d1d10.yaml (every field)", "layer": "corrective",
     "via": "governs_nothing (refused by DEC-20260923-a4c3d5)"},
]
narrow_rows = []
draft_amd = draft
for top in ("incorporates", "envelope_not_incorporated", "supersedes_fields", "custody_consequences",
            "span_rules", "corrective", "precedence", "governs_nothing", "authorization", "non_claims"):
    for p in leaves(draft_amd[top], top):
        if top == "span_rules":
            continue
        narrow_rows.append({"field": f"narrow:{p}", "layer": "corrective", "via": "this file"})
for sp in draft["span_rules"]:
    narrow_rows.append({"field": f"narrow:span_rules[{sp['id']}]", "layer": "corrective", "via": "this file"})

table = rows + v1_rows + other_rows + narrow_rows
fields = [r["field"] for r in table]
assert len(fields) == len(set(fields)), "duplicate field in table"
assert all(r["layer"] in ("v1", "refused-typed-by-hash", "corrective") for r in table)
checks["governing_text_table"] = {
    "rows": len(table),
    "by_layer": {k: sum(1 for r in table if r["layer"] == k) for k in ("v1", "refused-typed-by-hash", "corrective")},
    "typed_rows": len(rows), "v1_rows": len(v1_rows), "narrow_rows": len(narrow_rows),
    "duplicates": 0, "fields_with_two_layers": 0,
}
lines = []
for r in table:
    lines.append("    - {field: %s, layer: %s, via: %s}" % (json.dumps(r["field"]), r["layer"], json.dumps(r["via"])))
filled = filled.replace("@@GOVERNING_TEXT_TABLE@@", "\n".join(lines))
assert "@@" not in filled

# ------------------------------------------------------------------ final checks
final = yaml.safe_load(filled)["amendment"]
assert final["governing_text_table"] and len(final["governing_text_table"]) == len(table)
tools = final["corrective"]["tools"]
executed = json.load(open(f"{S}/admission_items.json"))["program_sha256"]
checks["programs"] = {
    "version_program": [sha(tools["version_program"]), tools["version_program_sha256"], executed["ITEM1_PARI_PROGRAM"]],
    "alarm_self_test_program": [sha(tools["alarm_self_test_program"]), tools["alarm_self_test_program_sha256"], executed["ITEM3_PROGRAM"]],
}
for k, v in checks["programs"].items():
    assert v[0] == v[1] == v[2], k

# spans re-verified from the final file
for sp in final["span_rules"]:
    assert sp["replaced_span_sha256"] == span_report[sp["id"]]["sha256"]
checks["spans"] = span_report

# retyping scan: no incorporated held string of >= 60 chars, and no 60-char window of one, appears in the narrow file
flat = re.sub(r"\s+", " ", filled)
retyped = []
for p in leaves(typed, ""):
    pass
def strings(node, path=""):
    if isinstance(node, dict):
        for k, v in node.items():
            yield from strings(v, f"{path}.{k}")
    elif isinstance(node, list):
        for n, x in enumerate(node):
            yield from strings(x, f"{path}[{n}]")
    elif isinstance(node, str):
        yield path, node
superseded_spans = []
for sp in draft["span_rules"]:
    val = resolve(typed, sp["field"])
    i = val.index(sp["from"]); j = val.index(sp["through"], i) + len(sp["through"])
    superseded_spans.append(val[i:j])
anchors = [sp["from"] for sp in draft["span_rules"]] + [sp["through"] for sp in draft["span_rules"]]
W = 60
for path, s in strings(typed):
    s2 = re.sub(r"\s+", " ", s)
    if len(s2) < W:
        continue
    for k in range(0, len(s2) - W + 1, 10):
        win = s2[k:k + W]
        if win in flat and not any(win in a for a in anchors) and not any(win in re.sub(r"\s+", " ", x) for x in superseded_spans):
            retyped.append({"held_field": path, "window": win})
            break
checks["retyping_scan"] = {"window_chars": W, "step": 10, "hits": retyped}

# forbidden values
forbidden = {
    "decimal_run_ge_16": re.findall(r"(?<![0-9A-Za-z])[0-9]{16,}(?![0-9A-Za-z])", filled),
    "hex_literal_0x_ge_16": re.findall(r"0x[0-9A-Fa-f]{16,}", filled),
    "c_field_expressions": [c["id"] for c in typed["controls"][[x["id"] for x in typed["controls"]].index("C-FIELD")]["cases"]
                            if any(t in filled.replace(" ", "") for t in re.findall(r"2\^[0-9]+", c["value"].replace(" ", "")))],
    "long_hex_not_digest_or_commit": [m for m in re.findall(r"(?<![0-9A-Za-z])[0-9a-fA-F]{20,}(?![0-9A-Za-z])", filled)
                                      if len(m) not in (40, 64)],
}
checks["forbidden_value_scan"] = forbidden
open(OUT, "w").write(filled)
checks["output_sha256"] = sha(filled)
checks["output_bytes"] = len(filled.encode())
json.dump(checks, open(REPORT, "w"), indent=1)
print(json.dumps({k: (v if k != "spans" else len(v)) for k, v in checks.items() if k not in ("retyping_scan",)}, indent=1))
print("retyping hits:", len(retyped))
for h in retyped[:20]:
    print(h)

